TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3 (c)"},{"id":"R4","met":"yes","where":"Question 4"},{"id":"R5","met":"yes","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"partial","where":"References"}],"technical_issues":[{"where":"Question 3 (c)","issue":"Payment availability was not combined with the other components. End-to-end availability should be about 99.80% and downtime about 1.5 h per month, not 99.9975% and 0.018 h."},{"where":"Question 3 (c)","issue":"Downtime of 0.018 h is inconsistent with the end-to-end calculation; 0.000025 × 720 is the payment-only downtime."},{"where":"Question 5 (ii)","issue":"CAP is misapplied: partition tolerance is not optional in a distributed system, and the text says consistency and availability are chosen while giving up partition tolerance."},{"where":"Question 1","issue":"The availability response measure 'stay up most of the time' is not quantified, so it is not measurable."},{"where":"Question 6","issue":"The ADR gives no negative consequence, such as added operational complexity or message-ordering and duplicate-delivery handling."},{"where":"Question 1","issue":"Stated word counts appear to exceed 150 words."},{"where":"Overall","issue":"No explicit assumptions section is provided, as required by R7."}],"overall":"Strong attribute choice, recommendation and Circuit Breaker answer. Q3(c) is wrong because it ignores the other components, and the CAP reasoning in Q5 is imprecise. Q6 lacks a negative consequence, several answers exceed 150 words, and assumptions are not stated.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Attributes are well justified from the scenario and the performance scenario is fully measurable. The availability scenario has all six parts but its response measure ('stay up most of the time') is not measurable, which places it at Proficient.","evidence":[{"where":"Question 1","quote":"The two most important quality attributes are performance and availability, because the business depends on the lunch hour"},{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"Clear recommendation with scenario-specific trade-offs: five-developer team size, single-VM lunchtime slowness and 20-minute weekly downtime. The downside is explicitly acknowledged.","evidence":[{"where":"Question 2","quote":"I recommend against a full microservices rewrite for the next 12 months."},{"where":"Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Proficient","mark":5.0,"scale":8.0,"points":5.0,"max":8.0,"reasoning":"Parts (a) and (b) are correct with working. Part (c) is wrong: the payment availability of 99.9975% was not combined with the other three components, so the end-to-end figure should be about 99.80% and downtime about 1.5 h, not 0.018 h. Exactly one part is incorrect.","evidence":[{"where":"Question 3 (a)","quote":"A = 0.9995 × 0.999 × 0.9995 × 0.995 = 0.99301"},{"where":"Question 3 (c)","quote":"So the new availability of placing an order is 99.9975%, which reduces the downtime to 0.000025 × 720 = 0.018 hours"}]},{"id":"C4","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Circuit Breaker is an appropriate pattern, correctly explained with its states and applied to the slow-provider outage. Threshold and wait-period tuning is mentioned only in passing and no explicit drawback is discussed, so it falls short of Excellent.","evidence":[{"where":"Question 4","quote":"The Circuit Breaker pattern [2] would have contained the failure."},{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Open"}]},{"id":"C5","level":"Proficient","mark":3.0,"scale":6.0,"points":3.0,"max":6.0,"reasoning":"Choices are reasonable and concrete techniques (TTL cache, idempotency keys) are named. The CAP explanation is imprecise: it contradicts the stated choice of consistency over availability and treats partition tolerance as optional in a distributed system.","evidence":[{"where":"Question 5 (ii)","quote":"we choose consistency and availability and give up partition tolerance"}]},{"id":"C6","level":"Proficient","mark":3.0,"scale":5.0,"points":3.0,"max":5.0,"reasoning":"Context, Decision and Consequences are all present and scenario-specific. The Consequences section lists only positive outcomes and omits any negative consequence, such as added infrastructure or queue ordering and delivery complexity.","evidence":[{"where":"Question 6","quote":"Consequences: Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Developing","mark":2.0,"scale":4.0,"points":2.0,"max":4.0,"reasoning":"Question 1 and Question 2 both appear to exceed the 150-word limit. Headings and IEEE citations [1] and [2] are correct, but several answers exceed the limit.","evidence":[{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]}]}
